package com.tiny.browser;public class MainActivity extends android.app.Activity{public void onCreate(android.os.Bundle b){super.onCreate(b);android.widget.EditText u=new android.widget.EditText(this);android.webkit.WebView w=new android.webkit.WebView(this);w.setWebViewClient(new android.webkit.WebViewClient());u.setSingleLine();android.widget.LinearLayout l=new android.widget.LinearLayout(this);l.setOrientation(1);l.addView(u,-1,-2);l.addView(w,-1,-1);setContentView(l);u.setOnEditorActionListener((v,a,e)->{String s=u.getText().toString();w.loadUrl(s.startsWith("http")?s:"https://"+s);return true;});}}
